+  const fort = new THREE.BatchedMesh(1, 24, 36, new THREE.MeshBasicMaterial());
+  fort.setMatrixAt(fort.addInstance(fort.addGeometry(new THREE.BoxGeometry(60, 6, 60))), new THREE.Matrix4());
